// Read the numbers from the stats query, not from this node input:
// between them sit the claim and the gate, whose payload is not the stats row.
const s = $('Query Last 24h').first().json;

const facts = [
  'processed events (24h): ' + s.processed_last_24h,
  'new leads (24h): ' + s.leads_last_24h,
  'support tickets (24h): ' + s.tickets_last_24h,
  'workflow errors (24h): ' + s.errors_last_24h,
  'items waiting in review queue (24h): ' + s.review_queue_last_24h,
].join('\n');

return [
  {
    json: {
      facts,
      errors: Number(s.errors_last_24h || 0),
      digestDate: $now.toFormat('yyyy-MM-dd'),
    },
  },
];

